int status = system("some_command arg");

// Check if system call itself failed
if (status == -1) {
    // Shell execution failed (e.g., out of memory)
}

// Command exited normally (check return code)
if (WIFEXITED(status)) {
    int exit_code = WEXITSTATUS(status);
    // 0 usually means success
}

// Command terminated due to signal
else if (WIFSIGNALED(status)) {
    int signal = WTERMSIG(status);
    // Check signal number (e.g., 9 for SIGKILL)
}
